<?php
/**
 * Plugin Name: Tisa Product ZIP Importer
 * Description: Imports product.zip files generated by the Tisa Telegram bot as WooCommerce draft variable products.
 * Version: 0.8.0
 * Requires Plugins: woocommerce
 * Author: علیرضا شعبان زاده
 */

if (!defined('ABSPATH')) exit;
if (!defined('TPI_VERSION')) define('TPI_VERSION', '0.8.0');

final class Tisa_Product_Zip_Importer {
    const NONCE = 'tisa_import_product_zip';
    const MAX_ZIP_BYTES = 33554432; // 32 MiB compressed.
    const MAX_UNCOMPRESSED_BYTES = 134217728; // 128 MiB total extracted.
    const MAX_ZIP_ENTRIES = 200;
    const MAX_IMAGES = 40;
    const MAX_IMAGE_BYTES = 12582912; // 12 MiB per image.
    const MAX_PRODUCT_JSON_BYTES = 2097152; // 2 MiB.
    const MAX_VARIATIONS = 500;
    const MAX_EXISTING_VARIATIONS = 500;
    const VARIATION_BATCH_SIZE = 20;
    const INLINE_VARIATIONS = 20;
    const INLINE_IMAGES = 5;
    const CATEGORY_PARENTS = [
        'استند و هولدر' => 'اکسسوری', 'بند قاب' => 'اکسسوری', 'پاپ سوکت و بند آویز' => 'اکسسوری',
        'پک محافظ شارژر' => 'اکسسوری', 'جا کارتی' => 'اکسسوری', 'جاکلیدی' => 'اکسسوری',
        'سرکلیدی' => 'اکسسوری', 'کابل جمع کن' => 'اکسسوری', 'کیف سیلیکونی' => 'اکسسوری',
