        'عروسکی' => 'قاب و کاور گوشی و تبلت', 'ست دو نفره' => 'قاب و کاور گوشی و تبلت',
        'سیلیکونی' => 'قاب و کاور گوشی و تبلت', 'گلس تبلت و آیپد' => 'گلس',
