        'Samsung Galaxy Buds' => 'لوازم جانبی ایرپاد', 'Airpods 1/2' => 'Apple AirPods',
        'Airpods 3' => 'Apple AirPods', 'Airpods 4' => 'Apple AirPods', 'Airpods Pro' => 'Apple AirPods',
