        echo '<div class="wrap tisa-wrap tisa-imp" dir="rtl"><h1 class="tisa-h1">افزودن یا شارژ محصول از تلگرام</h1>';
        self::notice();
        if (!empty($_GET['tisa_job'])) self::job_notice(sanitize_key(wp_unslash($_GET['tisa_job'])));
        if (!empty($_GET['tisa_product_id'])) {
            $created_id = absint($_GET['tisa_product_id']);
            if (get_post($created_id)) {
                // Build the URL explicitly. This avoids themes/admin scripts
                // filtering get_edit_post_link into an invalid value.
                $edit_url = admin_url('post.php?post=' . $created_id . '&action=edit');
                echo '<div class="notice notice-success tisa-notice tisa-notice--success"><p>محصول ساخته شد.</p>';
                echo '<p><a href="' . esc_url($edit_url) . '">' . esc_html($edit_url) . '</a></p></div>';
            }
