        echo '<form id="tisa-import-form" method="post" action="' . esc_url($form_action) . '" enctype="multipart/form-data">';
        echo '<input type="hidden" name="action" value="tisa_import_product">';
        echo '<input type="hidden" name="_wpnonce" value="' . esc_attr($nonce) . '">';
        echo '<section class="tisa-card tisa-imp__card">';
