        echo '<div class="tisa-imp__actions"><button id="tisa-submit" type="submit" class="tisa-btn tisa-btn--primary" disabled>ساخت محصول پیش‌نویس</button></div>';
        echo '</section></form>';
        echo '<details class="tisa-imp__help"><summary class="tisa-meta">چه چیزی ساخته می‌شود؟</summary><p class="tisa-meta">توضیحات محصول خالی می‌ماند. SKU اصلی توسط افزونه از روی آخرین SKU همان پیشوند ساخته می‌شود. SKU جداگانه برای variationها ساخته نمی‌شود.</p></details>';
        echo '<script>(function(){const f=document.getElementById("tisa-file"),z=document.getElementById("tisa-drop-zone"),n=document.getElementById("tisa-file-name"),b=document.getElementById("tisa-submit"),form=document.getElementById("tisa-import-form"),p=document.getElementById("tisa-progress"),s=document.getElementById("tisa-status");function setFile(file){if(!file||!/\\.zip$/i.test(file.name)){s.textContent="❌ فقط فایل ZIP مجاز است.";b.disabled=true;return}const dt=new DataTransfer();dt.items.add(file);f.files=dt.files;n.textContent="📦 "+file.name;b.disabled=false;s.textContent="فایل آمادهٔ ارسال است."}z.addEventListener("click",()=>f.click());z.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" ")f.click()});f.addEventListener("change",()=>setFile(f.files[0]));["dragenter","dragover"].forEach(e=>z.addEventListener(e,x=>{x.preventDefault();z.classList.add("is-over")}));["dragleave","drop"].forEach(e=>z.addEventListener(e,x=>{x.preventDefault();z.classList.remove("is-over")}));z.addEventListener("drop",e=>setFile(e.dataTransfer.files[0]));form.addEventListener("submit",e=>{e.preventDefault();b.disabled=true;p.style.display="block";p.removeAttribute("value");s.textContent="📤 در حال آپلود فایل...";const xhr=new XMLHttpRequest();xhr.open("POST",form.getAttribute("action"));xhr.upload.onprogress=e=>{if(e.lengthComputable){p.value=Math.round(e.loaded/e.total*100);s.textContent="📤 در حال آپلود فایل... "+p.value+"٪"}};s.textContent="⚙️ فایل روی سرور دریافت شد؛ پردازش واقعی ZIP و ساخت محصول در حال انجام است. لطفاً تا پایان این مرحله صفحه را نبندید...";xhr.onload=()=>{s.textContent="✅ پردازش سرور تمام شد؛ در حال نمایش نتیجه...";window.location.href=xhr.responseURL};xhr.onerror=()=>{s.textContent="❌ درخواست به سرور نرسید.";b.disabled=false};xhr.send(new FormData(form))});})();</script></div>';
