    private static function pending_selector($token) {
        $pending = get_transient('tisa_update_' . $token);
        if (!is_array($pending)) { echo '<div class="notice notice-error tisa-notice tisa-notice--danger"><p>اطلاعات شارژ منقضی شده است؛ ZIP را دوباره آپلود کنید.</p></div>'; return; }
        $data = $pending['data'];
        echo '<section class="tisa-card tisa-imp__card tisa-imp__card--wide"><h2 class="tisa-h2">انتخاب محصول برای شارژ</h2><p class="tisa-meta">محصول مناسب را انتخاب کنید. اگر در نتایج نبود، عنوان یا SKU را جستجو کنید.</p>';
        echo '<div class="tisa-imp__search"><input id="tisa-product-search" type="search" class="tisa-input" placeholder="جستجوی عنوان یا SKU…"><button id="tisa-search-btn" type="button" class="tisa-btn tisa-btn--secondary">جستجو</button></div>';
        echo '<div id="tisa-results" class="tisa-imp__results" role="radiogroup" aria-label="نتایج"></div>';
        echo '<div class="tisa-imp__actions"><button id="tisa-apply-update" class="tisa-btn tisa-btn--primary" disabled>اعمال شارژ روی محصول انتخاب‌شده</button><span id="tisa-update-status" class="tisa-meta" aria-live="polite"></span></div></section>';
        $ajax = admin_url('admin-ajax.php');
        $apply = admin_url('admin-post.php');
        $nonce = wp_create_nonce('tisa_update_' . $token);
        echo '<script>(function(){const q=document.getElementById("tisa-product-search"),r=document.getElementById("tisa-results"),b=document.getElementById("tisa-apply-update"),s=document.getElementById("tisa-update-status");let selected=0;q.value=' . wp_json_encode($data['title'] ?? '') . ';function search(){s.textContent="🔎 در حال جستجوی واقعی محصولات...";fetch(' . wp_json_encode($ajax) . '+"?action=tisa_search_existing_products&nonce="+' . wp_json_encode(wp_create_nonce('tisa_search_products')) . '+"&pending="+' . wp_json_encode($token) . '+"&q="+encodeURIComponent(q.value)).then(x=>x.json()).then(j=>{r.innerHTML="";selected=0;b.disabled=true;(j.data||[]).forEach(p=>{const row=document.createElement("label");row.className="tisa-imp__row";row.innerHTML=(p.image?"<img class=\"tisa-imp__thumb\" src=\""+p.image+"\" alt=\"\">":"<span class=\"tisa-imp__thumb tisa-imp__thumb--none\">بدون عکس</span>")+"<span class=\"tisa-imp__row-body\"><span><input type=radio name=tisa_product value="+p.id+"> <strong>"+p.title+"</strong></span><span class=\"tisa-imp__row-meta\"><span>SKU <b class=\"tisa-code\" dir=\"ltr\">"+(p.sku||"-")+"</b></span><span>قیمت فعلی <b class=\"tisa-num\">"+(p.price||"-")+"</b></span><span>ID <b class=\"tisa-code\">"+p.id+"</b></span></span><small class=\"tisa-meta\">ویژگی‌های فعلی: "+((p.attributes||[]).join(" | ")||"-")+"</small></span>";row.querySelector("input").onchange=()=>{selected=p.id;b.disabled=false};r.appendChild(row)});s.textContent=j.data&&j.data.length?"✅ محصول موردنظر را انتخاب کنید.":"محصولی پیدا نشد؛ عبارت دیگری جستجو کنید."}).catch(()=>s.textContent="❌ خطا در جستجو")};document.getElementById("tisa-search-btn").onclick=search;q.onkeydown=e=>{if(e.key==="Enter")search()};if(q.value)search();b.onclick=()=>{if(!selected)return;s.textContent="⚙️ در حال اعمال جایگزینی ویژگی‌ها و تاریخ محصول...";const f=new FormData();f.append("action","tisa_apply_update");f.append("_wpnonce",' . wp_json_encode($nonce) . ');f.append("token",' . wp_json_encode($token) . ');f.append("product_id",selected);fetch(' . wp_json_encode($apply) . ',{method:"POST",body:f}).then(x=>{window.location.href=x.url})}})();</script>';
    }

    private static function fail($message) {
        wp_safe_redirect(add_query_arg(['page'=>'tisa-product-importer','tisa_type'=>'error','tisa_notice'=>rawurlencode($message)], admin_url('admin.php')));
        exit;
    }

    private static function success($message, $product_id = 0, $job_id = '') {
        $args = ['page'=>'tisa-product-importer','tisa_type'=>'success','tisa_notice'=>$message];
        if ($product_id) $args['tisa_product_id'] = (int)$product_id;
        if ($job_id) $args['tisa_job'] = sanitize_key($job_id);
        wp_safe_redirect(add_query_arg($args, admin_url('admin.php')));
        exit;
    }

    public static function import() {
        if (!current_user_can('manage_woocommerce')) wp_die('دسترسی غیرمجاز');
        check_admin_referer(self::NONCE);
        if (!class_exists('WooCommerce')) self::fail('ووکامرس فعال نیست.');
        if (!class_exists('ZipArchive')) self::fail('افزونه PHP ZipArchive روی هاست فعال نیست. از پشتیبانی هاست بخواهید PHP ZIP را فعال کند.');
        if (empty($_FILES['product_zip']) || $_FILES['product_zip']['error'] !== UPLOAD_ERR_OK) self::fail('فایل ZIP دریافت نشد.');
        $file = $_FILES['product_zip'];
        if (strtolower(pathinfo($file['name'], PATHINFO_EXTENSION)) !== 'zip') self::fail('فقط فایل ZIP مجاز است.');
        if (empty($file['size']) || (int)$file['size'] > self::MAX_ZIP_BYTES) self::fail('حجم ZIP از سقف ۳۲ مگابایت بیشتر است.');

        $work_dir = self::private_workspace();
        if (!$work_dir) self::fail('پوشهٔ موقت خصوصی برای پردازش ZIP در دسترس نیست؛ تنظیمات temp هاست را بررسی کنید.');
        $tmp = trailingslashit($work_dir) . 'source.zip';
        if (!move_uploaded_file($file['tmp_name'], $tmp)) { self::remove_dir($work_dir); self::fail('ذخیره فایل آپلودشده ناموفق بود.'); }
        $actual_zip_bytes = @filesize($tmp);
        if (!$actual_zip_bytes || $actual_zip_bytes > self::MAX_ZIP_BYTES) { self::remove_dir($work_dir); self::fail('حجم ZIP از سقف ۳۲ مگابایت بیشتر است.'); }
        $dir = trailingslashit($work_dir) . 'payload';
        if (!wp_mkdir_p($dir)) { self::remove_dir($work_dir); self::fail('پوشهٔ موقت استخراج ساخته نشد.'); }
        $zip = new ZipArchive();
        $opened = $zip->open($tmp);
        if (true !== $opened) { @unlink($tmp); self::remove_workspace($dir); self::fail('فایل ZIP معتبر نیست یا قابل بازشدن نیست.'); }
        try {
            $zip_info = self::inspect_zip($zip, (int)$actual_zip_bytes);
            if (!$zip->extractTo($dir)) throw new RuntimeException('استخراج ZIP ناموفق بود.');
        } catch (Throwable $e) {
            $zip->close(); @unlink($tmp); self::remove_workspace($dir);
            self::fail($e->getMessage());
        }
        $zip->close();
        @unlink($tmp);

        $json = self::find_file($dir, 'product.json');
        if (!$json || !is_file($json) || filesize($json) > self::MAX_PRODUCT_JSON_BYTES) { self::remove_workspace($dir); self::fail('product.json وجود ندارد یا از سقف ۲ مگابایت بزرگ‌تر است.'); }
        $json_contents = file_get_contents($json);
        $data = is_string($json_contents) ? json_decode($json_contents, true) : null;
        if (!is_array($data)) { self::remove_workspace($dir); self::fail('product.json معتبر نیست.'); }
        try { self::validate_product_data($data); } catch (Throwable $e) { self::remove_workspace($dir); self::fail($e->getMessage()); }
        $title = sanitize_text_field($data['title'] ?? '');
        $price = (float)($data['price'] ?? 0);
        $prices = is_array($data['prices'] ?? null) ? array_map('floatval', $data['prices']) : [];
        if ($price <= 0 && $prices) $price = (float)reset($prices);
        $prefix = strtoupper(preg_replace('/[^A-Z0-9]/i', '', (string)($data['sku_prefix'] ?? '')));
        $models = self::values($data['models'] ?? []);
        $attrs = is_array($data['attributes'] ?? null) ? $data['attributes'] : [];
        $categories = self::values($data['categories'] ?? []);
        if (($data['mode'] ?? 'new') === 'update') {
            if ($price <= 0 && !$models && !$attrs) { self::remove_workspace($dir); self::fail('برای شارژ، حداقل قیمت یا ویژگی جدید لازم است.'); }
            try { self::variation_count(self::attributes_from_data($data)); } catch (Throwable $e) { self::remove_workspace($dir); self::fail($e->getMessage()); }
            $token = wp_generate_password(20, false, false);
            set_transient('tisa_update_' . $token, ['data'=>$data, 'dir'=>$dir], HOUR_IN_SECONDS);
            self::schedule_workspace_cleanup($dir, 2 * HOUR_IN_SECONDS);
            wp_safe_redirect(add_query_arg(['page'=>'tisa-product-importer', 'tisa_pending'=>$token], admin_url('admin.php')));
            exit;
        }

        if (!$title || $price <= 0 || !$prefix || !$models) { self::remove_workspace($dir); self::fail('عنوان، قیمت، پیشوند SKU یا مدل‌ها ناقص است.'); }
        try {
            $attrs = self::attributes_from_data($data);
            $variation_count = self::variation_count($attrs);
            $images = self::collect_images($dir);
        } catch (Throwable $e) { self::remove_workspace($dir); self::fail($e->getMessage()); }
        $is_variable = !empty($attrs);
        try { $sku = self::next_sku($prefix); } catch (Throwable $e) { self::remove_workspace($dir); self::fail($e->getMessage()); }
        $product_id = wp_insert_post([
            'post_title' => $title,
            'post_content' => '',
            'post_status' => 'draft',
            'post_type' => 'product',
            'post_author' => get_current_user_id(),
        ], true);
        if (is_wp_error($product_id) || !$product_id) { self::remove_workspace($dir); self::fail(is_wp_error($product_id) ? $product_id->get_error_message() : 'ساخت رکورد محصول ناموفق بود.'); }

        try {
            $image_ids = [];
            wp_set_object_terms($product_id, $is_variable ? 'variable' : 'simple', 'product_type');
            $woo_product = wc_get_product($product_id);
            if (!$woo_product) throw new RuntimeException('محصول ووکامرس برای ذخیره SKU ساخته نشد.');
            $woo_product->set_sku($sku);
            $woo_product->save();
            update_post_meta($product_id, '_visibility', 'visible');
            update_post_meta($product_id, '_stock_status', 'instock');
            update_post_meta($product_id, '_price', $price);
            update_post_meta($product_id, '_regular_price', $price);
            if ($is_variable) self::set_attributes($product_id, $attrs);
            self::set_categories($product_id, $categories);
            if ($variation_count > self::INLINE_VARIATIONS || count($images) > self::INLINE_IMAGES || $zip_info['uncompressed_bytes'] > 16777216 || $zip_info['entry_count'] > 40) {
                $job_id = self::queue_import_job($product_id, $attrs, $price, $prices, $dir, $images, $variation_count);
                self::success('محصول پیش‌نویس ساخته شد؛ ایجاد variationها و تصاویر در صف پس‌زمینه ادامه پیدا می‌کند.', $product_id, $job_id);
            }
            if ($images) self::attach_image_files($product_id, $images, 0, count($images), $image_ids);
            if ($image_ids) self::set_product_images($product_id, $image_ids);
            if ($is_variable) self::make_variations($product_id, $attrs, $price, $prices, $variation_count);
            if (class_exists('WC_Product_Variable') && $is_variable) WC_Product_Variable::sync($product_id);
            self::remove_workspace($dir);
            self::success('محصول با موفقیت ساخته شد.', $product_id);
        } catch (Throwable $e) {
            error_log('[Tisa Product Importer] ' . $e->getMessage() . ' in ' . $e->getFile() . ':' . $e->getLine());
            wp_delete_post($product_id, true);
            self::remove_workspace($dir);
            self::fail('ساخت محصول ناموفق بود: ' . $e->getMessage());
        }
    }

    /** Create a random 0700 staging directory outside public WordPress/upload roots. */
    private static function private_workspace() {
        $base = realpath(sys_get_temp_dir());
        if (!$base || !is_dir($base) || !is_writable($base)) return false;
        $roots = array(realpath(ABSPATH));
        if (!empty($_SERVER['DOCUMENT_ROOT'])) $roots[] = realpath($_SERVER['DOCUMENT_ROOT']);
        if (function_exists('wp_upload_dir')) {
            $uploads = wp_upload_dir();
            if (!empty($uploads['basedir'])) $roots[] = realpath($uploads['basedir']);
        }
        foreach ($roots as $root) {
            if (!$root) continue;
            $root = rtrim(wp_normalize_path($root), '/') . '/';
            $candidate = rtrim(wp_normalize_path($base), '/') . '/';
            if (0 === strpos($candidate, $root)) return false;
        }
        $path = trailingslashit($base) . 'tisa-import-' . wp_generate_password(24, false, false);
        if (!@mkdir($path, 0700) || !is_dir($path)) return false;
        @chmod($path, 0700);
        return realpath($path) ?: false;
    }

    private static function remove_workspace($payload_dir) {
        self::remove_dir($payload_dir);
        $parent = dirname((string)$payload_dir);
        if (0 === strpos(basename($parent), 'tisa-import-')) @rmdir($parent);
    }

    private static function schedule_workspace_cleanup($payload_dir, $delay, $job_id = '') {
        wp_schedule_single_event(time() + max(60, (int)$delay), 'tisa_product_import_cleanup_workspace', array((string)$payload_dir, (string)$job_id));
    }

    public static function cleanup_workspace_event($payload_dir, $job_id = '') {
        $temp = realpath(sys_get_temp_dir());
        $dir = realpath((string)$payload_dir);
        $parent = $dir ? realpath(dirname($dir)) : false;
        if (!$temp || !$dir || !$parent || basename($dir) !== 'payload' || !preg_match('/^tisa-import-[a-z0-9]+$/i', basename($parent))) return;
        $expected_parent = trailingslashit(wp_normalize_path($temp)) . basename($parent);
        if (wp_normalize_path($parent) !== untrailingslashit($expected_parent)) return;
        $job_id = sanitize_key((string)$job_id);
        if ($job_id) {
            $job = get_transient('tisa_import_job_' . $job_id);
            if (is_array($job) && !in_array(($job['status'] ?? ''), array('complete', 'failed'), true)) {
                $lock = get_option('tisa_import_lock_' . $job_id);
                if ($lock && time() - (int)$lock < 6 * HOUR_IN_SECONDS) {
                    self::schedule_workspace_cleanup($dir, DAY_IN_SECONDS, $job_id);
                    return;
                }
                if ($lock) delete_option('tisa_import_lock_' . $job_id);
                if (($job['type'] ?? 'new') !== 'update') {
                    foreach ((array)($job['image_ids'] ?? []) as $attachment_id) wp_delete_attachment((int)$attachment_id, true);
                    foreach (get_children(array('post_parent'=>(int)$job['product_id'], 'post_type'=>'product_variation', 'post_status'=>'any', 'fields'=>'ids')) as $variation_id) wp_delete_post($variation_id, true);
                    wp_delete_post((int)$job['product_id'], true);
                }
                $job['status'] = 'failed';
                $job['error'] = 'مدت مجاز اجرای کار پس‌زمینه تمام شد.';
                set_transient('tisa_import_job_' . $job_id, $job, DAY_IN_SECONDS);
            }
        }
        self::remove_workspace($dir);
    }

    /** Inspect every central-directory entry before allowing ZipArchive to write anything. */
    private static function inspect_zip($zip, $compressed_bytes) {
        if ($compressed_bytes <= 0 || $compressed_bytes > self::MAX_ZIP_BYTES) {
            throw new RuntimeException('حجم ZIP از سقف ۳۲ مگابایت بیشتر است.');
        }
        if (!isset($zip->numFiles) || $zip->numFiles < 1 || $zip->numFiles > self::MAX_ZIP_ENTRIES) {
            throw new RuntimeException('ZIP حداکثر می‌تواند ۲۰۰ ورودی داشته باشد.');
        }
        $entries = [];
        for ($index = 0; $index < $zip->numFiles; $index++) {
            $stat = $zip->statIndex($index);
            $name = $zip->getNameIndex($index);
            if (!is_array($stat) || !is_string($name)) throw new RuntimeException('فهرست داخلی ZIP معتبر نیست.');
            $symlink = false;
            if (method_exists($zip, 'getExternalAttributesIndex')) {
                $opsys = 0; $attributes = 0;
                if ($zip->getExternalAttributesIndex($index, $opsys, $attributes) && defined('ZipArchive::OPSYS_UNIX') && $opsys === ZipArchive::OPSYS_UNIX) {
                    $symlink = (((int)$attributes >> 16) & 0170000) === 0120000;
                }
            }
            $entries[] = [
                'name' => $name,
                'size' => isset($stat['size']) ? (int)$stat['size'] : -1,
                'compressed_size' => isset($stat['comp_size']) ? (int)$stat['comp_size'] : -1,
                'directory' => substr($name, -1) === '/',
                'symlink' => $symlink,
            ];
        }
        return self::validate_zip_entries($entries);
    }

    /** Pure validation shared with regression tests; no extraction or filesystem writes. */
    private static function validate_zip_entries($entries) {
        if (!is_array($entries) || count($entries) < 1 || count($entries) > self::MAX_ZIP_ENTRIES) {
            throw new RuntimeException('ZIP حداکثر می‌تواند ۲۰۰ ورودی داشته باشد.');
        }
        $total = 0; $images = 0; $json_files = 0; $seen = [];
        foreach ($entries as $entry) {
            if (!is_array($entry) || empty($entry['name']) || !isset($entry['size'], $entry['compressed_size'])) {
                throw new RuntimeException('یک ورودی ZIP اطلاعات ناقص دارد.');
            }
            $name = (string)$entry['name'];
            if (strlen($name) > 4096) throw new RuntimeException('مسیر یکی از فایل‌های ZIP بیش از حد طولانی است.');
            $normalized = str_replace('\\', '/', $name);
            $parts = explode('/', $normalized);
            if (strpos($normalized, "\0") !== false || $normalized[0] === '/' || preg_match('/^[A-Za-z]:/', $normalized) || in_array('..', $parts, true) || !empty($entry['symlink'])) {
                throw new RuntimeException('ZIP شامل مسیر ناامن یا پیوند نمادین است.');
            }
            if (isset($seen[$normalized])) throw new RuntimeException('ZIP شامل نام فایل تکراری است.');
            $seen[$normalized] = true;
            $size = (int)$entry['size']; $compressed = (int)$entry['compressed_size'];
            if ($size < 0 || $compressed < 0) throw new RuntimeException('اندازهٔ یکی از ورودی‌های ZIP معتبر نیست.');
            if (!empty($entry['directory'])) continue;
            if ($size > self::MAX_UNCOMPRESSED_BYTES - $total) throw new RuntimeException('حجم بازشدهٔ ZIP از سقف ۱۲۸ مگابایت بیشتر است.');
            $total += $size;
            if ($size > 0 && (0 === $compressed || $size > $compressed * 1000)) throw new RuntimeException('نسبت فشرده‌سازی یکی از فایل‌ها غیرمجاز است.');
            if (preg_match('/\.(jpe?g|png|webp)$/i', $normalized)) {
                $images++;
                if ($images > self::MAX_IMAGES) throw new RuntimeException('ZIP حداکثر می‌تواند ۴۰ تصویر داشته باشد.');
                if ($size > self::MAX_IMAGE_BYTES) throw new RuntimeException('حجم هر تصویر باید حداکثر ۱۲ مگابایت باشد.');
            }
            if (strtolower(basename($normalized)) === 'product.json') {
                $json_files++;
                if ($size > self::MAX_PRODUCT_JSON_BYTES) throw new RuntimeException('product.json حداکثر می‌تواند ۲ مگابایت باشد.');
            }
        }
        if ($json_files !== 1) throw new RuntimeException('ZIP باید دقیقاً یک product.json داشته باشد.');
        return ['uncompressed_bytes' => $total, 'images' => $images, 'entry_count' => count($entries)];
    }

    private static function validate_product_data($data) {
        $models = $data['models'] ?? [];
        $attrs = $data['attributes'] ?? [];
        $categories = $data['categories'] ?? [];
        $prices = $data['prices'] ?? [];
        if (isset($data['mode']) && !in_array($data['mode'], array('new', 'update'), true)) throw new RuntimeException('نوع عملیات ZIP معتبر نیست.');
        if (isset($data['image_mode']) && !in_array($data['image_mode'], array('keep', 'replace'), true)) throw new RuntimeException('حالت جایگزینی تصویر معتبر نیست.');
        if (!is_array($models) || count($models) > 500 || !is_array($attrs) || count($attrs) > 12 || !is_array($categories) || count($categories) > 100 || !is_array($prices) || count($prices) > 10) {
            throw new RuntimeException('تعداد مدل‌ها، ویژگی‌ها، دسته‌ها یا قیمت‌ها از سقف مجاز بیشتر است.');
        }
        if (isset($data['price']) && (!is_numeric($data['price']) || !is_finite((float)$data['price']))) throw new RuntimeException('قیمت محصول معتبر نیست.');
        foreach ($prices as $price) if (!is_numeric($price) || !is_finite((float)$price)) throw new RuntimeException('قیمت یکی از گروه‌ها معتبر نیست.');
        foreach (array('title', 'sku_prefix') as $field) if (isset($data[$field]) && (!is_scalar($data[$field]) || strlen((string)$data[$field]) > 500)) throw new RuntimeException('عنوان یا پیشوند SKU نامعتبر یا بیش از حد بزرگ است.');
        $total_values = count($models);
        foreach ($attrs as $name => $values) {
            if (!is_string($name) || strlen($name) > 200 || !is_array($values) || count($values) > 100) {
                throw new RuntimeException('ساختار یکی از ویژگی‌های محصول معتبر نیست یا از سقف مجاز بیشتر است.');
            }
            $total_values += count($values);
        }
        if ($total_values > 1000) throw new RuntimeException('مجموع گزینه‌های ویژگی از سقف ۱۰۰۰ مقدار بیشتر است.');
        foreach (array_merge($models, $categories) as $value) {
            if (!is_scalar($value) || strlen((string)$value) > 500) throw new RuntimeException('یکی از مقدارهای ZIP بیش از حد بزرگ یا نامعتبر است.');
        }
        foreach ($attrs as $values) foreach ($values as $value) {
            if (!is_scalar($value) || strlen((string)$value) > 500) throw new RuntimeException('یکی از مقدارهای ویژگی بیش از حد بزرگ یا نامعتبر است.');
        }
    }

    private static function attributes_from_data($data) {
        $models = self::values($data['models'] ?? []);
        $attrs = self::clean_attributes(is_array($data['attributes'] ?? null) ? $data['attributes'] : [], $models);
        if (count($models) >= 2) $attrs = array_merge(['مدل' => $models], $attrs);
        return $attrs;
    }

    /** Count the Cartesian product before any product/variation mutation. */
    private static function variation_count($attrs) {
        if (!$attrs) return 0;
        $count = 1;
        foreach ($attrs as $values) {
            $axis = is_array($values) ? count($values) : 0;
            if ($axis < 2) continue;
            if ($count > intdiv(self::MAX_VARIATIONS, $axis)) {
                throw new RuntimeException('این ZIP بیش از ۵۰۰ ترکیب متغیر می‌سازد؛ ویژگی‌ها را محدود یا فایل را به چند بخش تقسیم کنید.');
            }
            $count *= $axis;
        }
        if ($count > self::MAX_VARIATIONS) throw new RuntimeException('این ZIP بیش از ۵۰۰ ترکیب متغیر می‌سازد؛ ویژگی‌ها را محدود یا فایل را به چند بخش تقسیم کنید.');
        return $count;
    }

    private static function combination_at($attrs, $index) {
        $axes = [];
        foreach ($attrs as $name => $values) $axes[] = [$name, array_values($values)];
        $positions = array_fill(0, count($axes), 0);
        for ($axis = count($axes) - 1; $axis >= 0; $axis--) {
            $size = count($axes[$axis][1]);
            if ($size < 1) return [];
            $positions[$axis] = $index % $size;
            $index = intdiv($index, $size);
        }
        $combo = [];
        foreach ($axes as $i => $axis) $combo[$axis[0]] = $axis[1][$positions[$i]];
        return $combo;
    }

    private static function collect_images($dir) {
        $files = self::recursive_images($dir);
        if (count($files) > self::MAX_IMAGES) throw new RuntimeException('ZIP حداکثر می‌تواند ۴۰ تصویر داشته باشد.');
        foreach ($files as $file) {
            if (!is_file($file) || filesize($file) > self::MAX_IMAGE_BYTES) throw new RuntimeException('حجم هر تصویر باید حداکثر ۱۲ مگابایت باشد.');
        }
        sort($files, SORT_STRING);
        return $files;
    }

    private static function queue_import_job($product_id, $attrs, $price, $prices, $dir, $images, $variation_count) {
        $job_id = wp_generate_password(24, false, false);
        $job = [
            'status' => 'queued', 'product_id' => (int)$product_id, 'attrs' => $attrs,
            'price' => (float)$price, 'prices' => $prices, 'dir' => $dir,
            'images' => array_values($images), 'image_offset' => 0, 'image_ids' => [],
            'variation_count' => (int)$variation_count, 'variation_offset' => 0,
        ];
        if (!set_transient('tisa_import_job_' . $job_id, $job, 10 * DAY_IN_SECONDS)) throw new RuntimeException('ذخیرهٔ وضعیت کار پس‌زمینه ناموفق بود.');
        if (!self::schedule_import_job($job_id, false)) {
            delete_transient('tisa_import_job_' . $job_id);
            throw new RuntimeException('صف پس‌زمینه در دسترس نیست؛ محصول ساخته نشد.');
        }
        self::schedule_workspace_cleanup($dir, 7 * DAY_IN_SECONDS, $job_id);
        return $job_id;
    }

    private static function queue_update_job($product_id, $data, $dir, $variation_count) {
        $job_id = wp_generate_password(24, false, false);
        $job = array('type'=>'update', 'status'=>'queued', 'product_id'=>(int)$product_id, 'data'=>$data, 'dir'=>$dir, 'variation_count'=>(int)$variation_count, 'variation_offset'=>0, 'images'=>array(), 'image_offset'=>0, 'image_ids'=>array());
        if (!set_transient('tisa_import_job_' . $job_id, $job, 10 * DAY_IN_SECONDS)) throw new RuntimeException('ذخیرهٔ وضعیت شارژ پس‌زمینه ناموفق بود.');
        if (!self::schedule_import_job($job_id, false)) {
            delete_transient('tisa_import_job_' . $job_id);
            throw new RuntimeException('صف پس‌زمینه در دسترس نیست؛ شارژ انجام نشد.');
        }
        self::schedule_workspace_cleanup($dir, 7 * DAY_IN_SECONDS, $job_id);
        return $job_id;
    }

    private static function update_queue_plan($product_id, $data, $dir) {
        $models = self::values($data['models'] ?? array());
        $incoming_attrs = is_array($data['attributes'] ?? null) ? $data['attributes'] : array();
        $has_variation_update = !empty($models) || !empty($incoming_attrs) || !empty($data['prices']);
        $attrs = $has_variation_update ? self::updated_attributes($product_id, $models, $incoming_attrs) : array();
        $variation_count = $has_variation_update ? self::variation_count($attrs) : 0;
        $existing_count = count(self::existing_variation_ids($product_id));
        $image_count = (($data['image_mode'] ?? 'keep') === 'replace') ? count(self::collect_images($dir)) : 0;
        return array('queued'=>$variation_count > self::INLINE_VARIATIONS || $existing_count > self::INLINE_VARIATIONS || $image_count > self::INLINE_IMAGES, 'variation_count'=>$variation_count);
    }

    private static function schedule_import_job($job_id, $delayed = true) {
        $args = [$job_id];
        if (function_exists('as_enqueue_async_action')) {
            $action = as_enqueue_async_action('tisa_product_import_batch', $args, 'tisa-product-importer', true);
            if ($action) return true;
        }
        if (function_exists('as_schedule_single_action')) {
            $action = as_schedule_single_action(time() + ($delayed ? 10 : 1), 'tisa_product_import_batch', $args, 'tisa-product-importer', true);
            if ($action) return true;
        }
        $scheduled = wp_schedule_single_event(time() + ($delayed ? 10 : 1), 'tisa_product_import_batch', $args);
        return !is_wp_error($scheduled) && false !== $scheduled;
    }

    public static function process_import_batch($job_id) {
        $job_id = sanitize_key((string)$job_id);
        if (!$job_id) return;
        $lock_key = 'tisa_import_lock_' . $job_id;
        if (!add_option($lock_key, time(), '', false)) return;
        $job_key = 'tisa_import_job_' . $job_id;
        try {
            $job = get_transient($job_key);
            if (!is_array($job) || empty($job['product_id']) || empty($job['dir']) || !is_dir($job['dir'])) return;
            if (($job['type'] ?? 'new') === 'update') {
                $job['status'] = 'processing';
                if (!set_transient($job_key, $job, 10 * DAY_IN_SECONDS)) throw new RuntimeException('ذخیرهٔ وضعیت شارژ ناموفق بود.');
                self::update_existing_product((int)$job['product_id'], $job['data'], $job['dir']);
                self::remove_workspace($job['dir']);
                $job['status'] = 'complete';
                $job['completed_at'] = time();
                set_transient($job_key, $job, DAY_IN_SECONDS);
                return;
            }
            $job['status'] = 'processing';
            $count = (int)$job['variation_count'];
            $offset = (int)$job['variation_offset'];
            if ($offset < $count) {
                $limit = min(self::VARIATION_BATCH_SIZE, $count - $offset);
                self::make_variations_batch($job['product_id'], $job['attrs'], $job['price'], $job['prices'], $offset, $limit);
                $job['variation_offset'] += $limit;
            }
            $image_offset = (int)$job['image_offset'];
            if ($image_offset < count($job['images'])) {
                self::attach_image_files($job['product_id'], $job['images'], $image_offset, min(3, count($job['images']) - $image_offset), $job['image_ids']);
                $job['image_offset'] += min(3, count($job['images']) - $image_offset);
            }
            $done = $job['variation_offset'] >= $count && $job['image_offset'] >= count($job['images']);
            if ($done) {
                if (!empty($job['image_ids'])) self::set_product_images($job['product_id'], $job['image_ids']);
                if ($count && class_exists('WC_Product_Variable')) WC_Product_Variable::sync($job['product_id']);
                self::remove_workspace($job['dir']);
                $job['status'] = 'complete';
                $job['completed_at'] = time();
                set_transient($job_key, $job, DAY_IN_SECONDS);
                return;
            }
            if (!set_transient($job_key, $job, 10 * DAY_IN_SECONDS) || !self::schedule_import_job($job_id, true)) {
                throw new RuntimeException('ادامهٔ کار پس‌زمینه در صف ثبت نشد.');
            }
        } catch (Throwable $e) {
            $failed_job = isset($job) && is_array($job) ? $job : get_transient($job_key);
            if (is_array($failed_job)) {
                $job = $failed_job;
                if (($job['type'] ?? 'new') !== 'update') {
                    foreach ((array)($job['image_ids'] ?? []) as $attachment_id) wp_delete_attachment((int)$attachment_id, true);
                    foreach (get_children(['post_parent'=>(int)$job['product_id'], 'post_type'=>'product_variation', 'post_status'=>'any', 'fields'=>'ids']) as $variation_id) wp_delete_post($variation_id, true);
                    wp_delete_post((int)$job['product_id'], true);
                }
                self::remove_workspace($job['dir']);
                $job['status'] = 'failed';
                $job['error'] = sanitize_text_field($e->getMessage());
                set_transient($job_key, $job, DAY_IN_SECONDS);
            }
            error_log('[Tisa Product Importer batch] ' . $e->getMessage());
        } finally {
            delete_option($lock_key);
        }
    }

    private static function job_notice($job_id) {
        $job = get_transient('tisa_import_job_' . $job_id);
        if (!is_array($job)) return;
        if (($job['status'] ?? '') === 'complete') {
            $message = ($job['type'] ?? 'new') === 'update' ? 'شارژ پس‌زمینهٔ محصول کامل شد.' : 'ساخت variationها و تصاویر پس‌زمینه کامل شد.';
            echo '<div class="notice notice-success tisa-notice"><p>' . esc_html($message) . '</p></div>';
        } elseif (($job['status'] ?? '') === 'failed') {
            $message = ($job['type'] ?? 'new') === 'update' ? 'شارژ پس‌زمینه متوقف شد؛ ممکن است بخشی از تغییرات اعمال شده باشد. ' : 'کار پس‌زمینه متوقف شد: ';
            echo '<div class="notice notice-error tisa-notice"><p>' . esc_html($message . ($job['error'] ?? 'خطای نامشخص')) . '</p></div>';
        } elseif (($job['type'] ?? 'new') === 'update') {
            echo '<div class="notice notice-info tisa-notice"><p>شارژ محصول در صف پس‌زمینه است؛ برای تازه‌سازی وضعیت صفحه را دوباره باز کنید.</p></div>';
        } else {
            $done = (int)($job['variation_offset'] ?? 0); $total = (int)($job['variation_count'] ?? 0);
            $images_done = (int)($job['image_offset'] ?? 0); $images_total = count((array)($job['images'] ?? []));
            echo '<div class="notice notice-info tisa-notice"><p>ساخت در صف پس‌زمینه است: ' . esc_html((string)$done) . ' از ' . esc_html((string)$total) . ' variation و ' . esc_html((string)$images_done) . ' از ' . esc_html((string)$images_total) . ' تصویر؛ برای تازه‌سازی وضعیت صفحه را دوباره باز کنید.</p></div>';
        }
    }

    public static function search_existing_products() {
        if (!current_user_can('manage_woocommerce') || !wp_verify_nonce($_GET['nonce'] ?? '', 'tisa_search_products')) wp_send_json_error('دسترسی غیرمجاز', 403);
        $q = sanitize_text_field(wp_unslash($_GET['q'] ?? ''));
        $args = ['post_type'=>'product', 'post_status'=>['publish','draft','pending','private'], 'posts_per_page'=>30, 's'=> $q, 'orderby'=>'relevance'];
        $query = new WP_Query($args);
        $items = [];
        foreach ($query->posts as $post) {
            $items[] = self::candidate_data($post->ID);
        }
        if ($q !== '') {
            global $wpdb;
            $ids = $wpdb->get_col($wpdb->prepare("SELECT post_id FROM {$wpdb->postmeta} WHERE meta_key='_sku' AND meta_value LIKE %s LIMIT 30", '%' . $wpdb->esc_like($q) . '%'));
            foreach ($ids as $id) { $post=get_post($id); if ($post && $post->post_type==='product') $items[] = self::candidate_data($post->ID); }
        }
        $unique=[]; foreach ($items as $item) $unique[$item['id']]=$item;
        wp_send_json_success(array_values($unique));
    }

    private static function candidate_data($product_id) {
        $product = function_exists('wc_get_product') ? wc_get_product($product_id) : null;
        $attributes = [];
        if ($product) foreach ($product->get_attributes() as $attribute) $attributes[] = $attribute->get_name() . ': ' . implode(' | ', $attribute->get_options());
        return ['id'=>$product_id, 'title'=>get_the_title($product_id), 'sku'=>(string)get_post_meta($product_id, '_sku', true), 'price'=>$product ? $product->get_price() : '', 'attributes'=>$attributes, 'image'=>get_the_post_thumbnail_url($product_id, 'thumbnail') ?: ''];
    }

    public static function apply_update() {
        if (!current_user_can('manage_woocommerce')) wp_die('دسترسی غیرمجاز');
        $token = sanitize_text_field(wp_unslash($_POST['token'] ?? ''));
        check_admin_referer('tisa_update_' . $token);
        $pending = get_transient('tisa_update_' . $token);
        $product_id = absint($_POST['product_id'] ?? 0);
        if (!is_array($pending) || !$product_id || get_post_type($product_id) !== 'product') self::fail('اطلاعات شارژ یا محصول انتخاب‌شده معتبر نیست.');
        try {
            $plan = self::update_queue_plan($product_id, $pending['data'], $pending['dir']);
            if ($plan['queued']) {
                $job_id = self::queue_update_job($product_id, $pending['data'], $pending['dir'], $plan['variation_count']);
                delete_transient('tisa_update_' . $token);
                self::success('شارژ بزرگ محصول در صف پس‌زمینه ثبت شد؛ وضعیت را با تازه‌سازی صفحه پیگیری کنید.', $product_id, $job_id);
            }
            self::update_existing_product($product_id, $pending['data'], $pending['dir']);
            delete_transient('tisa_update_' . $token);
            self::remove_workspace($pending['dir']);
            self::success('شارژ محصول با موفقیت انجام شد.', $product_id);
        } catch (Throwable $e) {
            error_log('[Tisa Product Importer update] ' . $e->getMessage() . ' in ' . $e->getFile() . ':' . $e->getLine());
            delete_transient('tisa_update_' . $token);
            self::remove_workspace($pending['dir']);
            self::fail('شارژ محصول ناموفق بود: ' . $e->getMessage());
        }
    }

    private static function update_existing_product($product_id, $data, $dir) {
        $price = (float)($data['price'] ?? 0);
        $prices = is_array($data['prices'] ?? null) ? array_map('floatval', $data['prices']) : [];
        if ($price <= 0 && $prices) $price = (float)reset($prices);
        $models = self::values($data['models'] ?? []);
        $incoming_attrs = is_array($data['attributes'] ?? null) ? $data['attributes'] : [];
        $has_variation_update = !empty($models) || !empty($incoming_attrs) || !empty($prices);
        if ($price <= 0 && !$has_variation_update) throw new Exception('هیچ قیمت یا ویژگی جدیدی برای اعمال ارسال نشده است.');
        // Preflight the final merged matrix before changing price, attributes,
        // or deleting any existing variations.
        $attrs = $has_variation_update ? self::updated_attributes($product_id, $models, $incoming_attrs) : [];
        $variation_count = $has_variation_update ? self::variation_count($attrs) : 0;
        $existing_variations = self::existing_variation_ids($product_id);
        // No price in the restock ZIP means the current product price is
        // authoritative. Only overwrite it when a new price was supplied.
        $effective_price = $price > 0 ? $price : (float)get_post_meta($product_id, '_regular_price', true);
        if ($effective_price <= 0) {
            foreach ($existing_variations as $variation_id) {
                if (get_post_status($variation_id) === 'publish') { $effective_price = (float)get_post_meta($variation_id, '_regular_price', true); break; }
            }
        }
        if ($has_variation_update && !empty($attrs) && $effective_price <= 0) throw new Exception('قیمت فعلی محصول پیدا نشد.');
        if ($price > 0) {
            update_post_meta($product_id, '_regular_price', $price);
            update_post_meta($product_id, '_price', $price);
        }
        if ($has_variation_update) {
            $is_variable = !empty($attrs);
            wp_set_object_terms($product_id, $is_variable ? 'variable' : 'simple', 'product_type');
            if ($is_variable) {
                self::set_attributes($product_id, $attrs);
                self::replace_variations($product_id, $attrs, $effective_price, $prices, $variation_count, $existing_variations);
            } else {
                delete_post_meta($product_id, '_product_attributes');
                foreach ($existing_variations as $old) { wp_update_post(['ID'=>$old,'post_status'=>'private']); update_post_meta($old,'_stock_status','outofstock'); }
            }
        } elseif ($price > 0) {
            // Price-only restock: keep the existing attribute matrix and update
            // every live variation price without rebuilding combinations.
            foreach ($existing_variations as $variation_id) {
                if (get_post_status($variation_id) !== 'publish') continue;
                update_post_meta($variation_id, '_regular_price', $price);
                update_post_meta($variation_id, '_price', $price);
            }
        }
        if (($data['image_mode'] ?? 'keep') === 'replace') self::attach_images($product_id, $dir);
        $now = current_time('mysql');
        wp_update_post(['ID'=>$product_id, 'post_date'=>$now, 'post_date_gmt'=>get_gmt_from_date($now), 'post_modified'=>$now, 'post_modified_gmt'=>get_gmt_from_date($now)]);
        if (function_exists('wc_delete_product_transients')) wc_delete_product_transients($product_id);
    }

    private static function updated_attributes($product_id, $models, $incoming_attrs) {
        $attrs = self::clean_attributes($incoming_attrs, $models);
        $existing_attrs = [];
        global $wpdb;
        $existing_bytes = (int)$wpdb->get_var($wpdb->prepare("SELECT LENGTH(meta_value) FROM {$wpdb->postmeta} WHERE post_id=%d AND meta_key='_product_attributes' LIMIT 1", (int)$product_id));
        if ($existing_bytes > 262144) throw new RuntimeException('دادهٔ ویژگی محصول فعلی بیش از حد بزرگ است.');
        $existing = get_post_meta($product_id, '_product_attributes', true);
        if (is_array($existing)) {
            if (count($existing) > 12) throw new RuntimeException('محصول فعلی بیش از ۱۲ ویژگی دارد؛ شارژ خودکار متوقف شد.');
            $total_existing_values = 0;
            foreach ($existing as $attribute) {
                $name = (string)($attribute['name'] ?? '');
                $raw_values = (string)($attribute['value'] ?? '');
                if (strlen($raw_values) > 262144) throw new RuntimeException('دادهٔ ویژگی محصول فعلی بیش از حد بزرگ است.');
                $split_values = preg_split('/\s*\|\s*/u', $raw_values);
                if (!is_array($split_values) || count($split_values) > 500) throw new RuntimeException('ویژگی محصول فعلی بیش از ۵۰۰ مقدار دارد.');
                $values = self::values($split_values);
                $total_existing_values += count($values);
                if ($total_existing_values > 1000) throw new RuntimeException('مجموع گزینه‌های ویژگی محصول فعلی از سقف مجاز بیشتر است.');
                if ($name && count($values) >= 2) $existing_attrs[$name] = $values;
            }
        }
        if ($models) {
            foreach (array_keys($existing_attrs) as $existing_name) {
                if (in_array(mb_strtolower(trim($existing_name)), ['مدل', 'model'], true)) unset($existing_attrs[$existing_name]);
            }
            return array_merge(['مدل'=>$models], $existing_attrs, $attrs);
        }
        return array_merge($existing_attrs, $attrs);
    }

    private static function existing_variation_ids($product_id) {
        global $wpdb;
        $ids = $wpdb->get_col($wpdb->prepare(
            "SELECT ID FROM {$wpdb->posts} WHERE post_parent=%d AND post_type='product_variation' AND post_status NOT IN ('trash','auto-draft') ORDER BY ID ASC LIMIT %d",
            (int)$product_id,
            self::MAX_EXISTING_VARIATIONS + 1
        ));
        if (count((array)$ids) > self::MAX_EXISTING_VARIATIONS) {
            throw new RuntimeException('محصول فعلی بیش از ۵۰۰ variation دارد؛ شارژ خودکار برای جلوگیری از عملیات سنگین متوقف شد.');
        }
        return array_map('intval', (array)$ids);
    }

    private static function replace_variations($product_id, $attrs, $price, $prices = [], $variation_count = null, $old_variations = []) {
        // The preflight list is capped; never load/delete an unbounded child set.
        foreach ($old_variations as $old) wp_delete_post((int)$old, true);
        self::make_variations($product_id, $attrs, $price, $prices, $variation_count);
    }

    private static function values($value) {
        if (!is_array($value)) return [];
        $out = [];
        foreach ($value as $v) { $v = sanitize_text_field((string)$v); if ($v !== '' && !in_array($v, $out, true)) $out[] = $v; }
        return $out;
    }

    private static function clean_attributes($attrs, $models) {
        $out = [];
        foreach ($attrs as $name => $values) {
            $name = sanitize_text_field((string)$name);
            if (!$name || in_array(mb_strtolower($name), ['مدل','model'], true) || !is_array($values)) continue;
            $values = self::values($values);
            // One value gives the customer nothing to choose, so it is part
            // of the product identity rather than a WooCommerce attribute.
            if (count($values) >= 2) $out[$name] = $values;
        }
        return $out;
    }

    private static function next_sku($prefix) {
        global $wpdb;
        $table = $wpdb->prefix . 'wc_product_meta_lookup';
        $exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($table)));
        if ($exists !== $table) throw new RuntimeException('جدول جست‌وجوی SKU ووکامرس در دسترس نیست؛ همگام‌سازی جدول محصولات را بررسی کنید.');
        $like = $wpdb->esc_like($prefix) . '%';
        // WooCommerce indexes this lookup table's SKU column; avoid loading every
        // _sku row from postmeta into PHP for each import.
        $pattern = '^' . preg_quote($prefix, '/') . '[0-9]+$';
        $max = (int)$wpdb->get_var($wpdb->prepare(
            "SELECT COALESCE(MAX(CAST(SUBSTRING(sku,%d) AS UNSIGNED)),0) FROM {$table} WHERE sku LIKE %s AND sku REGEXP %s",
            strlen($prefix) + 1,
            $like,
            $pattern
        ));
        for ($attempt = 0; $attempt < 1000; $attempt++) {
            $candidate = $prefix . (++$max);
            if (!function_exists('wc_get_product_id_by_sku') || !wc_get_product_id_by_sku($candidate)) return $candidate;
        }
        throw new RuntimeException('ساخت SKU یکتا ممکن نشد؛ یک بار دیگر تلاش کنید.');
    }

    private static function set_attributes($product_id, $attrs) {
        $meta = [];
        foreach ($attrs as $name => $values) {
            $slug = sanitize_title($name);
            $meta[$slug] = ['name'=>$name, 'value'=>implode(' | ', $values), 'position'=>count($meta), 'is_visible'=>1, 'is_variation'=>1, 'is_taxonomy'=>0];
        }
        update_post_meta($product_id, '_product_attributes', $meta);
    }

    private static function set_categories($product_id, $categories) {
        $ids = [];
        foreach ($categories as $path) {
            if (in_array(trim($path), ['فروش ویژه','💥 بلک فرایدی','محصولات عمده'], true)) continue;
            $parts = preg_split('/\s*(?:>|\/|»|→)\s*/u', trim($path));
            $parts = self::complete_category_path($parts);
            $parent = 0; $last = 0;
            foreach ($parts as $part) {
                $part = trim($part); if ($part === '') continue;
                $term = get_terms(['taxonomy'=>'product_cat','name'=>$part,'parent'=>$parent,'hide_empty'=>false,'number'=>1]);
                if (!empty($term) && !is_wp_error($term)) $last = (int)$term[0]->term_id;
                else { $created = wp_insert_term($part, 'product_cat', ['parent'=>$parent]); if (is_wp_error($created)) continue; $last = (int)$created['term_id']; }
                // WooCommerce/WordPress does not automatically assign every
                // ancestor when a child is assigned. Keep the complete path:
                // parent first, then child, exactly as selected in the editor.
                $ids[] = $last;
                $parent = $last;
            }

        }
        if ($ids) wp_set_object_terms($product_id, array_unique($ids), 'product_cat', false);
    }

    private static function complete_category_path($parts) {
        $parts = array_values(array_filter(array_map('trim', (array)$parts)));
        if (count($parts) !== 1) return $parts;
        $chain = [$parts[0]]; $current = $parts[0]; $guard = 0;
        while (isset(self::CATEGORY_PARENTS[$current]) && $guard++ < 10) {
            $current = self::CATEGORY_PARENTS[$current];
            array_unshift($chain, $current);
        }
        return $chain;
    }

    private static function price_for_combo($combo, $default, $prices) {
        if (!$prices || empty($combo)) return $default;
        foreach ($combo as $name => $value) {
            if (mb_strtolower(trim($name)) !== 'مدل' && mb_strtolower(trim($name)) !== 'model') continue;
            $model = mb_strtolower((string)$value);
            $group = preg_match('/\\biphone\\b/i', $model) ? 'iphone' : 'android';
            if (!empty($prices[$group])) return (float)$prices[$group];
        }
        return $default;
    }

    private static function make_variations($product_id, $attrs, $price, $prices = [], $count = null) {
        $count = null === $count ? self::variation_count($attrs) : (int)$count;
        for ($offset = 0; $offset < $count; $offset += self::VARIATION_BATCH_SIZE) {
            self::make_variations_batch($product_id, $attrs, $price, $prices, $offset, min(self::VARIATION_BATCH_SIZE, $count - $offset));
        }
    }

    /** Create only a bounded slice; never materialize the full Cartesian matrix. */
    private static function make_variations_batch($product_id, $attrs, $price, $prices, $offset, $limit) {
        $count = self::variation_count($attrs);
        $end = min($count, max(0, (int)$offset) + max(0, (int)$limit));
        for ($index = max(0, (int)$offset); $index < $end; $index++) {
            $combo = self::combination_at($attrs, $index);
            if (!$combo) continue;
            $variation_price = self::price_for_combo($combo, $price, $prices);
            $variation = new WC_Product_Variation();
            $variation->set_parent_id($product_id);
            $variation->set_status('publish');
            $variation->set_regular_price((string)$variation_price);
            $variation->set_price((string)$variation_price);
            $variation->set_manage_stock(false);
            $variation->set_stock_status('instock');
            $variation_attributes = [];
            foreach ($combo as $name => $value) $variation_attributes[sanitize_title($name)] = sanitize_title($value);
            $variation->set_attributes($variation_attributes);
            $variation_id = $variation->save();
            foreach ($combo as $name => $value) update_post_meta($variation_id, 'attribute_' . sanitize_title($name), sanitize_title($value));
            clean_post_cache($variation_id);
        }
    }

    private static function attach_images($product_id, $dir) {
        $files = self::collect_images($dir);
        $ids = [];
        if ($files) self::attach_image_files($product_id, $files, 0, count($files), $ids);
        if ($ids) self::set_product_images($product_id, $ids);
    }

    private static function attach_image_files($product_id, $files, $offset, $limit, &$ids) {
        require_once ABSPATH . 'wp-admin/includes/file.php';
        require_once ABSPATH . 'wp-admin/includes/media.php';
        require_once ABSPATH . 'wp-admin/includes/image.php';
        $end = min(count($files), max(0, (int)$offset) + max(0, (int)$limit));
        for ($index = max(0, (int)$offset); $index < $end; $index++) {
            $file = $files[$index];
            if (!is_file($file) || filesize($file) > self::MAX_IMAGE_BYTES) throw new RuntimeException('حجم هر تصویر باید حداکثر ۱۲ مگابایت باشد.');
            $contents = file_get_contents($file);
            if (!is_string($contents)) throw new RuntimeException('خواندن یکی از تصویرها ناموفق بود.');
            $upload = wp_upload_bits(basename($file), null, $contents);
            unset($contents);
            if (!empty($upload['error'])) continue;
            $type = wp_check_filetype($upload['file']);
            $attachment = ['post_mime_type'=>$type['type'], 'post_title'=>sanitize_file_name(pathinfo($file, PATHINFO_FILENAME)), 'post_status'=>'inherit'];
            $id = wp_insert_attachment($attachment, $upload['file'], $product_id);
            if (!$id) continue;
            wp_update_attachment_metadata($id, wp_generate_attachment_metadata($id, $upload['file']));
            $ids[] = (int)$id;
        }
    }

    private static function set_product_images($product_id, $ids) {
        if ($ids) {
            set_post_thumbnail($product_id, (int)$ids[0]);
            update_post_meta($product_id, '_product_image_gallery', implode(',', array_map('intval', array_slice($ids, 1))));
        }
    }

    private static function recursive_images($dir) {
        $out = []; $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS));
        foreach ($it as $f) if (preg_match('/\.(jpe?g|png|webp)$/i', $f->getFilename())) $out[] = $f->getPathname();
        return $out;
    }

    private static function find_file($dir, $name) {
        $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS));
        foreach ($iterator as $file) if ($file->isFile() && $file->getFilename() === $name) return $file->getPathname();
        return false;
    }

    private static function remove_dir($dir) {
        if (!is_dir($dir)) return; $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST);
        foreach ($it as $f) $f->isDir() ? @rmdir($f->getPathname()) : @unlink($f->getPathname()); @rmdir($dir);
    }
}
Tisa_Product_Zip_Importer::init();
